import { ImageZoom } from "@likashefqet/react-native-image-zoom";
import { Block, Text } from "@prototyp/skeletor";
import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import { type FC, useCallback, useEffect, useState } from "react";
import {
  StyleSheet,
  TouchableOpacity,
  useWindowDimensions,
} from "react-native";
import { Colors, TextSize } from "shared/styles";
import { resolveEncryptedImage } from "shared/utils/encrypted-image-cache";
import { Loading } from "../loading";
import { getImageContent } from "./utils";

interface Props {
  event: EventTimelineItem;
  onSingleTap: () => void;
  onLocalUriChange: (uri: string | null) => void;
}

export const MediaImagePage: FC<Props> = ({
  event,
  onSingleTap,
  onLocalUriChange,
}) => {
  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
  const content = getImageContent(event);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);

  const load = useCallback(async () => {
    if (!content) {
      setHasError(true);
      setIsLoading(false);
      return null;
    }
    const mxcUrl = content.source.url();
    if (!mxcUrl) {
      setHasError(true);
      setIsLoading(false);
      return null;
    }
    try {
      const resolved = await resolveEncryptedImage({
        cacheKey: mxcUrl,
        mediaSource: content.source,
        mimeType: content.info?.mimetype || "image/jpeg",
      });
      return resolved ?? null;
    } catch {
      return null;
    }
  }, [content]);

  useEffect(() => {
    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    load().then((uri) => {
      if (cancelled) return;
      if (uri) {
        setLocalUri(uri);
      } else {
        setHasError(true);
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [load]);

  useEffect(() => {
    onLocalUriChange(localUri);
  }, [localUri, onLocalUriChange]);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);
    const uri = await load();
    if (uri) {
      setLocalUri(uri);
    } else {
      setHasError(true);
      setIsLoading(false);
    }
  }, [load]);

  return (
    <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
      {isLoading && !hasError && (
        <Block
          absolute
          width={SCREEN_WIDTH}
          height={SCREEN_HEIGHT}
          align="center"
          justify="center"
          background={Colors.white10}
        >
          <Loading isFullScreen={false} />
        </Block>
      )}
      {hasError ? (
        <Block
          width={SCREEN_WIDTH}
          height={SCREEN_HEIGHT}
          align="center"
          justify="center"
        >
          <Text color={Colors.white}>Failed to load image</Text>
          <TouchableOpacity onPress={handleRetry} style={styles.retryButton}>
            <Text size={TextSize.small} color={Colors.white}>
              Tap to retry
            </Text>
          </TouchableOpacity>
        </Block>
      ) : localUri ? (
        <ImageZoom
          key={localUri}
          uri={localUri}
          minScale={1}
          maxScale={5}
          maxPanPointers={2}
          isPanEnabled
          isPinchEnabled
          isDoubleTapEnabled
          isSingleTapEnabled
          style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
          onLoad={handleImageLoad}
          onError={handleImageError}
          onSingleTap={onSingleTap}
        />
      ) : null}
    </Block>
  );
};

const styles = StyleSheet.create({
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import { FlashList } from "@shopify/flash-list";
import type {
  EventTimelineItem,
  ImageMessageContent,
  VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { type FC, useCallback } from "react";
import { StyleSheet } from "react-native";
import { Loading } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MediaThumbnail } from "../media-thumbnail";

const NUM_COLUMNS = 4;
const SPACING = 2;

const keyExtractor = (item: EventTimelineItem) => {
  const eventId = item.eventOrTransactionId;
  if (eventId?.tag === "EventId") return eventId.inner.eventId;
  if (eventId?.tag === "TransactionId") return eventId.inner.transactionId;
  return String(item.timestamp);
};

interface Props {
  items: EventTimelineItem[];
  loading: boolean;
  paginating: boolean;
  isEmpty: boolean;
  onPressItem: (
    uri: string | null,
    type?: "image" | "video",
    content?: ImageMessageContent | VideoMessageContent,
    event?: EventTimelineItem,
  ) => void;
  onEndReached?: () => void;
}

export const MediaList: FC<Props> = ({
  items,
  loading,
  paginating,
  isEmpty,
  onPressItem,
  onEndReached,
}) => {
  const ListEmpty = useCallback(() => {
    if (loading) {
      return (
        <Block align="center" justify="center" flex={1} paddings={40}>
          <Loading isFullScreen={false} />
        </Block>
      );
    }

    return (
      <Block align="center" justify="center" flex={1} paddings={40}>
        <Text size={TextSize.medium} color={Colors.white50}>
          No media found
        </Text>
      </Block>
    );
  }, [loading]);

  return (
    <FlashList
      data={items}
      renderItem={({ item, index }) => (
        <Block
          margins={{
            marginRight: (index + 1) % NUM_COLUMNS === 0 ? 0 : SPACING,
            marginBottom: SPACING,
          }}
        >
          <MediaThumbnail item={item} onPress={onPressItem} />
        </Block>
      )}
      keyExtractor={keyExtractor}
      numColumns={NUM_COLUMNS}
      contentContainerStyle={styles.listContent}
      ListEmptyComponent={ListEmpty}
      ListFooterComponent={
        (loading || paginating) && !isEmpty ? (
          <Block align="center" justify="center" flex={1} paddings={40}>
            <Loading isFullScreen={false} />
          </Block>
        ) : null
      }
      onEndReached={onEndReached}
      onEndReachedThreshold={0.5}
      showsVerticalScrollIndicator={false}
    />
  );
};

const styles = StyleSheet.create({
  listContent: {
    padding: SPACING,
    flexGrow: 1,
  },
});

