28	import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
29	import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
30	import { useMediaTimeline } from "screens/room-media/hooks";
31	import { Colors, TextSize } from "shared/styles";
32	import { BlurGradientOverlay } from "../blur-gradient-overlay";
