34	import { MediaEdgePage } from "./MediaEdgePage";
35	import { MediaImagePage } from "./MediaImagePage";
36	import { MediaVideoPage } from "./MediaVideoPage";
37	import { getMediaKind } from "./utils";
38	
39	const OLDER_EDGE_KEY = "__older_edge__";
40	
41	type ViewerPage =
