240	    >
241	      <BottomSheetModalProvider>
242	        <Block background={Colors.black} flex={1}>
243	          <FlatList
244	            data={pages}
245	            renderItem={renderItem}
246	            keyExtractor={keyExtractor}
247	            getItemLayout={getItemLayout}
248	            horizontal
249	            inverted={payload.source === "timeline"}
250	            pagingEnabled
251	            showsHorizontalScrollIndicator={false}
252	            initialScrollIndex={initialPageIndex}
253	            onViewableItemsChanged={handleViewableItemsChanged}
254	          />
255	
256	          <Block
257	            absolute
258	            offsets={{ top: 0, left: 0, right: 0 }}
259	            zIndex={10}
260	            paddings={[56, 20, 16, 20]}
261	            flexDirection="row"
262	            align="center"
263	            justify="space-between"
264	            gap={12}
265	            background={Colors.primary}
266	            animations={controlsAnimation.animations}
267	            pointerEvents={showControls ? "auto" : "none"}
268	          >
269	            <BlurGradientOverlay />
270	            <Block width={60} align="flex-start" zIndex={2}>
271	              {!!currentEvent && (
272	                <Button.Wrapper onPress={handleOpenInfo}>
273	                  <Image
274	                    source={require("assets/icons/info.png")}
275	                    style={styles.infoIcon}
276	                    tintColor={Colors.white}
277	                  />
278	                </Button.Wrapper>
279	              )}
280	            </Block>
281	            <Block flex={1} align="center" gap={2} zIndex={2}>
282	              {senderName && (
283	                <Text
284	                  color={Colors.white}
285	                  font="InstrumentSans-Semibold"
286	                  numberOfLines={1}
287	                >
288	                  {senderName}
289	                </Text>
290	              )}
291	              {formattedDate && (
292	                <Text
293	                  size={TextSize.tiny}
294	                  color={Colors.white80}
295	                  numberOfLines={1}
296	                >
297	                  {formattedDate}
298	                </Text>
299	              )}
300	            </Block>
301	            <Block width={60} align="flex-end" zIndex={2}>
302	              <Button.Wrapper onPress={onClose}>
303	                <Text font="InstrumentSans-Semibold" color={Colors.white}>
304	                  Close
305	                </Text>
306	              </Button.Wrapper>
307	            </Block>
308	          </Block>
309	        </Block>
310	        <ImageInfoBottomSheet />
311	        <VideoInfoBottomSheet />
312	      </BottomSheetModalProvider>
313	    </Modal>
314	  );
315	};
316	
317	const styles = StyleSheet.create({
318	  infoIcon: {
319	    width: 24,
320	    height: 24,
321	  },
322	});
