        } else {
          setHasError(true);
          setIsLoading(false);
        }
      });

      return () => {
        cancelled = true;
      };
    }, [eventId]);

    useEffect(() => {
      onLocalUriChange(eventId, localUri);
    }, [eventId, localUri, onLocalUriChange]);

