      loadRef.current().then((uri) => {
        if (cancelled) return;
        if (uri) {
          setLocalUri(uri);
        } else {
          setHasError(true);
          setIsLoading(false);
        }
      });

      return () => {
        cancelled = true;
      };
    }, [eventId]);

    useEffect(() => {
      onLocalUriChange(eventId, localUri);
    }, [eventId, localUri, onLocalUriChange]);

