/** True once the modal's own timeline has paginated far enough back to
contain the tapped event. The gallery auto-paginates aggressively, so its
list can include items deeper than this modal's first page. */
const hasInitialEvent = useMemo(
  () =>
    mediaItems.some((e) => getEventId(e) === payload.initialEventId),
  [mediaItems, payload.initialEventId],
);

/** Filtered events sorted newest-first. Until the tapped event has been
paginated in, render just the seed so the user lands on the right page. */
const events = useMemo<EventTimelineItem[]>(() => {
  if (!hasInitialEvent) return [payload.initialEvent];
  return mediaItems.filter((item) => getMediaKind(item) !== null);
}, [mediaItems, payload.initialEvent, hasInitialEvent]);

/** FlatList data: events + a trailing "older-edge" sentinel while more
history remains. Swiping onto the sentinel triggers `loadMore`; incoming
events land between the last real event and the sentinel, so the user
slides from the spinner onto the newest item of the just-loaded batch.
Suppressed during initial pagination so the seeded single-item render
can't accidentally land on it. */
const pages = useMemo<ViewerPage[]>(() => {
  const result: ViewerPage[] = events.map((event) => ({
    kind: "event",
    event,
  }));
  if (!loading && !reachedStart) result.push({ kind: "older-edge" });
  return result;
}, [events, loading, reachedStart]);

